'use strict';
// Maquette autonome : aucun accès au plugin, au système de fichiers ou à QGIS.
const paths = {
  'chevron-down':'<path d="m6 9 6 6 6-6"/>','arrow-right':'<path d="M5 12h14M14 7l5 5-5 5"/>','arrow-up-right':'<path d="M7 17 17 7M8 7h9v9"/>',
  check:'<path d="m5 12 4 4L19 6"/>',grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .7-1.5 1-1.5 2.5M12 17h.01"/>',layout:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16M9 10h12"/>',
  database:'<ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v7c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12v7c0 1.7 3.6 3 8 3s8-1.3 8-3v-7"/>',
  'check-circle':'<circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/>',layers:'<path d="m12 3 9 5-9 5-9-5 9-5ZM3 12l9 5 9-5M3 16l9 5 9-5"/>',
  settings:'<circle cx="12" cy="12" r="3"/><path d="M19.4 15a2 2 0 0 0 .4 2.2l.1.1-2 3.4-.2-.1a2 2 0 0 0-2.2.3l-.1.1h-4l-.1-.2a2 2 0 0 0-2-.9l-.3.1-2-3.4.1-.2a2 2 0 0 0-.4-2.2l-.1-.1v-4l.2-.1a2 2 0 0 0 .9-2l-.1-.3 3.4-2 .2.1a2 2 0 0 0 2.2-.4l.1-.1h4l.1.2a2 2 0 0 0 2 .9l.3-.1 2 3.4-.1.2a2 2 0 0 0 .4 2.2l.1.1v4Z"/>',
  folder:'<path d="M3 6a2 2 0 0 1 2-2h5l2 2h7a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>',
  spark:'<path d="m12 3 1.7 5.3L19 10l-5.3 1.7L12 17l-1.7-5.3L5 10l5.3-1.7L12 3ZM19 15l.7 2.3L22 18l-2.3.7L19 21l-.7-2.3L16 18l2.3-.7L19 15Z"/>',
  compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5L16 8Z"/>',activity:'<path d="M3 12h4l2-6 4 12 3-8 2 2h3"/>',
  pin:'<path d="M19 10c0 5-7 11-7 11S5 15 5 10a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2"/>',route:'<circle cx="6" cy="5" r="2"/><circle cx="18" cy="19" r="2"/><path d="M6 7v4c0 4 12 0 12 5v1"/>',
  flask:'<path d="M9 3h6M10 3v6l-5 9a2 2 0 0 0 2 3h10a2 2 0 0 0 2-3l-5-9V3M8 15h8"/>',
  navigation:'<path d="m12 3 6 18-6-4-6 4 6-18Z"/>',maximize:'<path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/>',x:'<path d="M6 6l12 12M18 6 6 18"/>'
};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name] || ''}</svg>`}
function addIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
addIcons();
const dialog=document.querySelector('#dialog'), body=document.querySelector('#dialogBody');
let returnFocus=null;
function openDialog(title, content, eyebrow='PROTOTYPE · SIMULATION'){
  returnFocus=document.activeElement; document.querySelector('#dialogTitle').textContent=title;document.querySelector('#dialogEyebrow').textContent=eyebrow;body.innerHTML=content;addIcons(body);dialog.showModal();
}
function closeDialog(){dialog.close();if(returnFocus) returnFocus.focus()}
document.querySelector('#closeDialog').onclick=closeDialog;document.querySelector('#dialogDone').onclick=closeDialog;
let toastTimer;function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200)}
const steps={
 project:{title:'Projet',text:'Configurez le nom, le dossier et le système de coordonnées avant de préparer les données.',extra:'Le SCR du jeu d’exemple est EPSG:32629. Ce prototype ne crée aucun projet.',button:'Détails du projet'},
 data:{title:'Données',text:'Rassemblez vos fichiers de forage, puis vérifiez les colonnes et les éventuelles anomalies.',extra:'Le jeu fictif présente les collets, déviations, lithologies et teneurs. Les autres familles restent à concevoir.',button:'Voir les familles'},
 geometry:{title:'Trajectoires',text:'Préparez la visualisation des forages à partir des collets et des mesures de déviation.',extra:'La méthode, les conventions et les hypothèses devront être validées. Aucun calcul n’est exécuté ici.',button:'Comprendre cette étape'},
 section:{title:'Coupe',text:'Définissez une ligne de coupe et explorez les données en profondeur.',extra:'Le tracé sur la carte est une illustration. La création de coupe sera conçue dans une étape ultérieure.',button:'Comprendre cette étape'}
};
let currentStep='data';
function selectStep(key){currentStep=key;document.querySelectorAll('.step').forEach(x=>x.classList.toggle('selected',x.dataset.step===key));document.querySelector('#nextButton').innerHTML=`Voir l’étape ${steps[key].title} ${icon('arrow-right')}`;toast(`Étape ${steps[key].title} sélectionnée · aperçu conceptuel`)}
document.querySelectorAll('.step').forEach(btn=>btn.addEventListener('click',()=>selectStep(btn.dataset.step)));
function openStep(){const s=steps[currentStep];openDialog(`Étape · ${s.title}`,`<p>${s.text}</p><div class="summary-card"><div class="summary-icon">${icon('info')}</div><div><strong>Ce que montre cette première version</strong><small>${s.extra}</small></div></div><h3>Suite de conception</h3><p>Cet espace est maintenant disponible sous forme de simulation interactive, sans traitement géologique réel.</p>${currentStep==='project'?'':`<button class="primary-button modal-action" data-goto-step="${currentStep}">Ouvrir l’espace ${icon('arrow-right')}</button>`}`)}
document.querySelector('#nextButton').onclick=openStep;
function showProject(){openDialog('Projet Démonstration',`<p>Un contexte de projet lisible et toujours accessible, coordonné avec les espaces de visualisation.</p><div class="hole-detail"><span>Système de coordonnées</span><strong>EPSG:32629</strong></div><div class="hole-detail"><span>Référence</span><strong>WGS 84 / UTM zone 29N</strong></div><div class="hole-detail"><span>Données</span><strong>3 forages fictifs</strong></div><p style="margin-top:16px">Aucun projet QGIS n’est ouvert ou créé par cette maquette.</p>`,'CONTEXTE DU PROJET')}
document.querySelector('#projectButton').onclick=showProject;document.querySelector('#projectInfo').onclick=showProject;
function showFamilies(){openDialog('Familles de données',`<p>Les familles de la V1 restent distinctes. Les quatre premières sont illustrées dans ce jeu fictif ; les autres seront étudiées lors de la déclinaison des modules.</p><h3>Exemples disponibles</h3><div class="dialog-list"><span class="tag">Collets</span><span class="tag">Déviations</span><span class="tag">Lithologie</span><span class="tag">Teneurs</span></div><h3>Familles à représenter ensuite</h3><div class="dialog-list"><span class="tag">Altérations</span><span class="tag">Minéralisations</span><span class="tag">Structures</span><span class="tag">Imagerie</span><span class="tag">RQD</span><span class="tag">Récupération</span><span class="tag">Densité</span></div>`,'DONNÉES · PÉRIMÈTRE')}
document.querySelector('#familiesButton').onclick=showFamilies;document.querySelector('#allData').onclick=showFamilies;
document.querySelector('#helpButton').onclick=()=>openDialog('À propos de cette maquette','<p>Cette première version permet d’évaluer l’organisation générale et le langage visuel de DrillMaster.</p><p>Les données et la carte sont fictives. Aucun fichier n’est ouvert, aucune géométrie n’est calculée et aucune commande QGIS n’est exécutée.</p><p>Cinq espaces de travail sont désormais simulés ; les autres modules ne sont pas encore maquettés.</p>');
document.querySelector('#settingsButton').onclick=()=>openDialog('Paramètres et préférences','<p>Leur organisation est encore à valider. La conception distingue les <strong>paramètres du projet</strong> (SCR et conventions), les <strong>préférences personnelles</strong> (langue et disposition) et les réglages de chaque vue.</p><p>Une préférence personnelle ne doit pas modifier silencieusement une convention scientifique du projet.</p>');
document.querySelector('#designButton').onclick=()=>openDialog('Atelier géologique',`<p>Un langage visuel calme pour laisser les données géologiques au premier plan. Cette palette est une proposition à tester avec les thèmes et les tailles système de QGIS.</p><div class="swatches"><div class="swatch"><i style="background:#263c32"></i>Navigation<br>#263C32</div><div class="swatch"><i style="background:#315c48"></i>Action<br>#315C48</div><div class="swatch"><i style="background:#f5f6f3"></i>Surface<br>#F5F6F3</div><div class="swatch"><i style="background:#c48d5c"></i>Repère<br>#C48D5C</div><div class="swatch"><i style="background:#202c28"></i>Texte<br>#202C28</div></div><h3>Principes</h3><p>Typographie système · espacements 4 / 8 / 12 / 16 / 24 · contrôles sobres · statuts explicites · focus visible. Les composants doivent s’adapter aux thèmes de QGIS, sans imposer ces couleurs aux données.</p><button class="primary-button modal-action" id="sampleButton">Exemple de bouton ${icon('arrow-right')}</button><label class="demo-field">Exemple de champ<input value="Projet Démonstration" aria-label="Exemple de champ de démonstration"></label><p>Les exemples ci-dessus ne modifient aucun projet.</p>`,'DESIGN SYSTEM · V01');
body.addEventListener('click',event=>{if(event.target.closest('#sampleButton'))toast('Action de démonstration uniquement');const link=event.target.closest('[data-goto-step]');if(link&&window.openPrototypeWorkspace){closeDialog();window.openPrototypeWorkspace(({data:'import',geometry:'trajectory',section:'section'})[link.dataset.gotoStep]);}});
const holes={'DM-001':{depth:'100 m',orientation:'0° / −90°',location:'500 000 E · 800 000 N'},'DM-002':{depth:'100 m',orientation:'90° / −45°',location:'500 100 E · 800 000 N'},'DM-003':{depth:'120 m',orientation:'0° / −60°',location:'500 200 E · 800 000 N'}};
function selectHole(id){document.querySelectorAll('#holeTable tr').forEach(x=>x.classList.toggle('selected-row',x.dataset.hole===id));document.querySelectorAll('.map-hole').forEach(x=>x.classList.toggle('selected-hole',x.dataset.hole===id));const h=holes[id];openDialog(`Forage ${id}`,`<p>Exemple de sélection partagée entre le tableau et le schéma. Les valeurs ci-dessous proviennent du jeu fictif.</p><div class="hole-detail"><span>Collet</span><strong>${h.location}</strong></div><div class="hole-detail"><span>Profondeur</span><strong>${h.depth}</strong></div><div class="hole-detail"><span>Azimut / dip</span><strong>${h.orientation}</strong></div><p style="margin-top:16px">Le schéma n’est pas une carte géoréférencée et aucune trajectoire n’est calculée.</p>`,'SÉLECTION · DONNÉES FICTIVES')}
document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>selectHole(b.dataset.select));document.querySelectorAll('.map-hole').forEach(g=>{g.addEventListener('click',()=>selectHole(g.dataset.hole));g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectHole(g.dataset.hole)}})});
const map=document.querySelector('#mapSvg'),mapWrap=document.querySelector('#mapWrap');let zoom=1;
function setZoom(value){zoom=Math.min(1.5,Math.max(1,value));map.style.transform=`scale(${zoom})`;toast(`Zoom du schéma : ${Math.round(zoom*100)} %`)}
document.querySelector('#zoomIn').onclick=()=>setZoom(zoom+.15);document.querySelector('#zoomOut').onclick=()=>setZoom(zoom-.15);document.querySelector('#zoomReset').onclick=()=>setZoom(1);
document.querySelector('#layersButton').onclick=()=>openDialog('Couches de la carte','<p>La carte ci-contre est un schéma, pas une carte QGIS. Elle montre trois collets fictifs et un tracé de coupe illustratif.</p><p>La gestion réelle des couches sera étudiée lors de la déclinaison de la visualisation.</p>');
let placeholder=null;
document.querySelectorAll('.view-tab').forEach(btn=>btn.onclick=()=>{const view=btn.dataset.view;document.querySelectorAll('.view-tab').forEach(x=>{const active=x===btn;x.classList.toggle('active',active);x.setAttribute('aria-selected',String(active))});if(placeholder){placeholder.remove();placeholder=null}map.style.display=view==='map'?'block':'none';document.querySelector('.map-compass').style.display=view==='map'?'flex':'none';document.querySelector('.map-scale').style.display=view==='map'?'flex':'none';document.querySelector('.map-zoom').style.display=view==='map'?'flex':'none';document.querySelector('#mapTitle').textContent=view==='map'?'EMPLACEMENT DES FORAGES':view==='section'?'COUPE 2D · À CONCEVOIR':'VUE 3D · À CONCEVOIR';if(view!=='map'){placeholder=document.createElement('div');placeholder.className='visual-placeholder';placeholder.innerHTML=`<div><strong>${view==='section'?'Coupe 2D':'Vue 3D'}</strong><p>La vue simulée est disponible dans l’espace Visualisation. Aucun calcul réel n’est exécuté.</p><button class="ws-btn primary" style="margin-top:14px" id="openViewSpace">Ouvrir la visualisation</button></div>`;mapWrap.appendChild(placeholder);}});
document.querySelectorAll('[data-nav]').forEach(btn=>btn.onclick=()=>{document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x===btn));switch(btn.dataset.nav){case 'workspace':toast('Espace de travail');break;case 'data':selectStep('data');showFamilies();break;case 'quality':openDialog('Contrôle qualité','<p>Ce point d’accès est réservé au futur tableau de validation : anomalies groupées, gravité, emplacement et correction assistée.</p><p>La validation n’est pas un traitement réel : utilisez l’espace de contrôle qualité simulé.</p>');break;case 'visual':document.querySelector('.visual-panel').scrollIntoView({behavior:'smooth',block:'center'});toast('Visualisation sélectionnée');break}});
dialog.addEventListener('cancel',()=>{if(returnFocus)setTimeout(()=>returnFocus.focus(),0)});

mapWrap.addEventListener('click',e=>{if(e.target.closest('#openViewSpace')&&window.openPrototypeWorkspace)window.openPrototypeWorkspace('visual')});
